import { Metadata } from 'next';
import Contact from '@/components/sections/Contact';
import Footer from '@/components/sections/Footer';
import TeamGrid from '@/components/sections/about/TeamGrid';

export const metadata: Metadata = {
    title: 'About Us | Greenberg Engineering',
    description: 'Building the infrastructure intelligence layer for India. Led by Devansh Gulati and Gunjan Singh.',
};

export default function AboutPage() {
    return (
        <main className="bg-void min-h-screen pt-24">
            <div className="container mx-auto px-6 pt-12 pb-12 text-center">
                <span className="font-mono text-stark/40 text-xs tracking-[0.2em] uppercase mb-6 block">
                    Our Mission
                </span>
                <h1 className="font-heading text-4xl md:text-6xl font-bold text-stark max-w-4xl mx-auto leading-tight mb-8">
                    Building the <span className="text-[#2C5DA9]">Brain</span> for
                    India's Infrastructure.
                </h1>
                <p className="font-body text-xl text-stark/60 max-w-2xl mx-auto mb-12">
                    We combine deep structural expertise with cutting-edge intelligence to ensure every project is safe, compliant, and optimized for tomorrow.
                </p>
                <div className="h-px w-24 bg-gradient-to-r from-transparent via-stark/20 to-transparent mx-auto" />
            </div>

            <TeamGrid />
            <Contact />
            <Footer />
        </main>
    );
}

'use client';

import { motion } from 'framer-motion';
import Footer from '@/components/sections/Footer';
import ParallaxHero from '@/components/ui/ParallaxHero';
import SectorNavigation from '@/components/ui/SectorNavigation';
import JobBoard from '@/components/company/JobBoard';
import SpotlightCard from '@/components/ui/SpotlightCard';
import { Target, Users, Zap } from 'lucide-react';

const culture = [
    {
        title: 'Radical Ownership',
        description: 'We don’t have managers; we have leaders. You own your outcomes.',
        icon: Target
    },
    {
        title: 'Continuous Growth',
        description: 'Unlimited access to courses, certifications, and mentorship.',
        icon: Zap
    },
    {
        title: 'Collaborative Genius',
        description: 'Work alongside the best minds in structural and digital engineering.',
        icon: Users
    }
];

export default function CareersPage() {
    return (
        <main className="bg-void min-h-screen">
            <ParallaxHero
                title="Careers"
                highlight="Impact"
                description="We are always looking for visionaries who want to build the future of infrastructure. If you thrive on challenge, we want you."
                sectorId="00"
                gradient="linear-gradient(135deg, #EC954E 0%, #FFD9B2 100%)"
            />

            {/* Culture Grid */}
            <section className="container mx-auto px-6 md:px-12 lg:px-24 py-24 relative z-10 -mt-20">
                <div className="grid md:grid-cols-3 gap-6">
                    {culture.map((item, index) => (
                        <SpotlightCard key={item.title} className="h-full bg-void border-white/5">
                            <div className="p-8 h-full">
                                <item.icon className="w-8 h-8 text-[#EC954E] mb-6" />
                                <h3 className="font-heading text-xl text-stark mb-3">{item.title}</h3>
                                <p className="font-body text-stark/50 text-sm leading-relaxed">
                                    {item.description}
                                </p>
                            </div>
                        </SpotlightCard>
                    ))}
                </div>
            </section>

            {/* Job Board */}
            <section className="container mx-auto px-6 md:px-12 lg:px-24 py-24 border-t border-white/5">
                <div className="flex flex-col md:flex-row justify-between items-baseline mb-16">
                    <div>
                        <h2 className="font-heading text-4xl text-stark mb-2">Open Positions</h2>
                        <p className="font-body text-stark/50">Join our mission.</p>
                    </div>
                </div>
                <JobBoard />
            </section>

            <SectorNavigation
                nextSector={{
                    name: "Contact",
                    href: "/#contact",
                    tagline: "Let's build something iconic.",
                    color: "#D40114"
                }}
            />

            <Footer />
        </main>
    );
}

