interface MagneticInputProps {
    label: string;
    name: string;
    type: string;
    placeholder: string;
    required?: boolean;
    value?: string;
    onChange?: (value: string) => void;
}

function MagneticInput({ label, name, type, placeholder, required, value, onChange }: MagneticInputProps) {
    const inputRef = useRef<HTMLInputElement | HTMLTextAreaElement>(null);
    const [isFocused, setIsFocused] = useState(false);

    const fieldValue = value ?? '';
    const isTextarea = type === 'textarea';
    const Component = isTextarea ? 'textarea' : 'input';

    return (
        <div className="relative group">
            <label
                className={`
                    absolute left-0 top-0 font-mono text-xs uppercase tracking-widest transition-all duration-300 pointer-events-none z-10
                    ${isFocused || fieldValue ? '-translate-y-6 text-[#8D68AA]' : 'translate-y-4 text-stark/40'}
                `}
            >
                {label}
            </label>

            <Component
                ref={inputRef as React.Ref<HTMLInputElement & HTMLTextAreaElement>}
                name={name}
                value={fieldValue}
                placeholder={placeholder}
                required={required}
                onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => onChange?.(e.target.value)}
                onFocus={() => setIsFocused(true)}
                onBlur={() => setIsFocused(false)}
                rows={isTextarea ? 4 : undefined}
                className={`
                    w-full bg-transparent border-b border-white/10 py-4 text-lg font-body text-stark
                    placeholder:text-stark/20 focus:outline-none focus:border-transparent transition-all relative z-10
                    ${isTextarea ? 'resize-none' : ''}
                `}
            />

            {/* Custom Interactive Border */}
            <div className="absolute bottom-0 left-0 w-full h-[1px] bg-white/10 overflow-hidden">
                {/* Spotlight effect that follows mouse horizontally when hovered/focused */}
                <motion.div
                    className="absolute top-0 bottom-0 w-full bg-gradient-to-r from-transparent via-[#8D68AA] to-transparent h-[2px]"
                    initial={{ x: '-100%' }}
                    animate={{
                        x: isFocused ? '0%' : '-100%',
                        opacity: isFocused ? 1 : 0
                    }}
                    transition={{ duration: 0.5 }}
                />
            </div>

            {/* Dot Animation on Focus */}
            <motion.div
                className="absolute right-0 bottom-4 w-2 h-2 rounded-full bg-[#8D68AA]"
                initial={{ scale: 0 }}
                animate={{ scale: isFocused ? 1 : 0 }}
                transition={{ type: "spring", stiffness: 300, damping: 20 }}
            >
                <div className="absolute inset-0 bg-[#8D68AA] animate-ping rounded-full opacity-50" />
            </motion.div>
        </div>
    );
}

interface Star {
    x: number;
    y: number;
    size: number;
    delay: number;
}

function ConstellationField({ mouseX, mouseY }: { mouseX: ReturnType<typeof useMotionValue<number>>, mouseY: ReturnType<typeof useMotionValue<number>> }) {
    const [stars, setStars] = useState<Star[]>([]);

    useEffect(() => {
        setStars(Array.from({ length: 40 }).map((_, i) => ({
            x: Math.random() * 100,
            y: Math.random() * 100,
            size: Math.random() * 2 + 1,
            delay: Math.random() * 5
        })));
    }, []);

    return (
        <div className="absolute inset-0 pointer-events-none">
            {/* Gradient Orb following mouse */}
            <motion.div
                className="absolute w-[600px] h-[600px] bg-gradient-radial from-[#8D68AA]/10 to-transparent rounded-full blur-[100px]"
                style={{
                    x: mouseX,
                    y: mouseY,
                    translateX: '-50%',
                    translateY: '-50%'
                }}
            />

            {/* Stars */}
            {stars.map((star, i) => (
                <motion.div
                    key={i}
                    className="absolute bg-white rounded-full"
                    style={{
                        left: `${star.x}%`,
                        top: `${star.y}%`,
                        width: star.size,
                        height: star.size,
                    }}
                    animate={{
                        opacity: [0.1, 0.5, 0.1],
                        scale: [1, 1.2, 1],
                    }}
                    transition={{
                        duration: 3 + Math.random() * 2,
                        repeat: Infinity,
                        delay: star.delay
                    }}
                />
            ))}

            {/* Connecting Lines (Simulated Constellation) */}
            <svg className="absolute inset-0 w-full h-full opacity-20">
                <motion.line
                    x1="10%" y1="20%" x2="30%" y2="40%"
                    stroke="white" strokeWidth="0.5" strokeDasharray="5 5"
                    animate={{ strokeDashoffset: [0, 10] }}
                    transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
                />
                <motion.line
                    x1="30%" y1="40%" x2="70%" y2="30%"
                    stroke="white" strokeWidth="0.5" strokeDasharray="5 5"
                    animate={{ strokeDashoffset: [0, 10] }}
                    transition={{ duration: 25, repeat: Infinity, ease: "linear" }}
                />
                <motion.line
                    x1="70%" y1="30%" x2="80%" y2="80%"
                    stroke="white" strokeWidth="0.5" strokeDasharray="5 5"
                    animate={{ strokeDashoffset: [0, 10] }}
                    transition={{ duration: 30, repeat: Infinity, ease: "linear" }}
                />
            </svg>
        </div>
    );
}

