import { MotionValue } from 'framer-motion';

function ShieldVisualization({ scrollProgress }: { scrollProgress: MotionValue<number> }) {
    const shieldProgress = useTransform(scrollProgress, [0.1, 0.45], [0, 1]);

    return (
        <div className="relative w-full h-full flex items-center justify-center">
            <svg
                viewBox="0 0 200 250"
                className="w-full h-full max-w-[350px]"
                fill="none"
            >
                {/* Shield outline */}
                <motion.path
                    d="M100 10 L180 40 L180 120 Q180 200 100 240 Q20 200 20 120 L20 40 Z"
                    stroke="#D40114"
                    strokeWidth="2"
                    fill="none"
                    style={{
                        pathLength: shieldProgress,
                    }}
                />

                {/* Inner shield glow */}
                <motion.path
                    d="M100 30 L160 55 L160 115 Q160 180 100 215 Q40 180 40 115 L40 55 Z"
                    fill="url(#shieldGlow)"
                    style={{
                        opacity: useTransform(scrollProgress, [0.2, 0.4], [0, 0.3]),
                    }}
                />

                {/* Checkmark in center */}
                <motion.path
                    d="M70 120 L90 140 L130 90"
                    stroke="#D40114"
                    strokeWidth="6"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    fill="none"
                    style={{
                        pathLength: useTransform(scrollProgress, [0.35, 0.5], [0, 1]),
                    }}
                />

                {/* Protective rays */}
                {[0, 45, 90, 135, 180, 225, 270, 315].map((angle, i) => (
                    <ProtectiveRay key={angle} angle={angle} index={i} scrollProgress={scrollProgress} />
                ))}

                {/* Gradient definition */}
                <defs>
                    <radialGradient id="shieldGlow" cx="50%" cy="50%" r="50%">
                        <stop offset="0%" stopColor="#D40114" stopOpacity="0.3" />
                        <stop offset="100%" stopColor="#A20505" stopOpacity="0" />
                    </radialGradient>
                </defs>
            </svg>

            {/* Protective aura */}
            <motion.div
                className="absolute w-80 h-80 rounded-full"
                style={{
                    background: `radial-gradient(circle, rgba(212, 1, 20, 0.1) 0%, transparent 70%)`,
                }}
                animate={{
                    scale: [1, 1.1, 1],
                    opacity: [0.3, 0.5, 0.3],
                }}
                transition={{
                    duration: 2,
                    repeat: Infinity,
                    ease: 'easeInOut',
                }}
            />
        </div>
    );
}

function ProtectiveRay({ angle, index, scrollProgress }: { angle: number, index: number, scrollProgress: MotionValue<number> }) {
    const radians = (angle * Math.PI) / 180;
    const x1 = 100 + Math.cos(radians) * 100;
    const y1 = 125 + Math.sin(radians) * 100;
    const x2 = 100 + Math.cos(radians) * 130;
    const y2 = 125 + Math.sin(radians) * 130;
    const opacity = useTransform(scrollProgress, [0.4 + index * 0.02, 0.5 + index * 0.02], [0, 0.3]);

    return (
        <motion.line
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            stroke="#D40114"
            strokeWidth="1"
            style={{ opacity }}
        />
    );
}

function HeartbeatLine({ scrollProgress }: { scrollProgress: MotionValue<number> }) {
    return (
        <div className="absolute bottom-1/3 left-0 right-0 h-20 overflow-hidden pointer-events-none opacity-30">
            <svg
                className="w-[200%] h-full"
                viewBox="0 0 1200 80"
                preserveAspectRatio="none"
            >
                <motion.path
                    d="M0 40 L200 40 L220 40 L240 10 L260 70 L280 40 L300 40 
             L500 40 L520 40 L540 10 L560 70 L580 40 L600 40
             L800 40 L820 40 L840 10 L860 70 L880 40 L900 40
             L1000 40 L1020 40 L1040 10 L1060 70 L1080 40 L1200 40"
                    stroke="#D40114"
                    strokeWidth="2"
                    fill="none"
                    initial={{ x: 0 }}
                    animate={{ x: -600 }}
                    transition={{
                        duration: 3,
                        repeat: Infinity,
                        ease: 'linear',
                    }}
                />
            </svg>
        </div>
    );
}

'use client';

import { motion, useMotionValue, useSpring } from 'framer-motion';
import { useRef, ReactNode } from 'react';

interface MagneticButtonProps {
    children: ReactNode;
    className?: string;
    onClick?: () => void;
    href?: string;
    strength?: number;
    type?: 'button' | 'submit' | 'reset';
}

export default function MagneticButton({
    children,
    className = '',
    onClick,
    href,
    strength = 0.3,
    type = 'button',
}: MagneticButtonProps) {
    const ref = useRef<HTMLDivElement>(null);

    const x = useMotionValue(0);
    const y = useMotionValue(0);

    const springConfig = { damping: 15, stiffness: 150 };
    const xSpring = useSpring(x, springConfig);
    const ySpring = useSpring(y, springConfig);

    const handleMouseMove = (e: React.MouseEvent) => {
        if (!ref.current) return;
        const rect = ref.current.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;

        x.set((e.clientX - centerX) * strength);
        y.set((e.clientY - centerY) * strength);
    };

    const handleMouseLeave = () => {
        x.set(0);
        y.set(0);
    };

    const Component = href ? motion.a : motion.button;

    return (
        <Component
            ref={ref as React.Ref<any>}
            href={href}
            onClick={onClick}
            type={!href ? type : undefined}
            className={`relative overflow-hidden group ${className}`}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            style={{ x: xSpring, y: ySpring }}
            whileTap={{ scale: 0.95 }}
            data-cursor
        >
            {/* Background fill */}
            <motion.span
                className="absolute inset-0 bg-stark"
                initial={{ scaleX: 0 }}
                whileHover={{ scaleX: 1 }}
                transition={{ duration: 0.4, ease: [0.25, 0.46, 0.45, 0.94] }}
                style={{ transformOrigin: 'left' }}
            />

            {/* Content */}
            <span className="relative z-10 flex items-center gap-2 text-stark group-hover:text-void transition-colors duration-300">
                {children}
            </span>

            {/* Glow effect */}
            <motion.span
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none"
                style={{
                    boxShadow: '0 0 40px rgba(255,255,255,0.2)',
                }}
            />
        </Component>
    );
}
